import{_ as t,o as e,c as a,a7 as i,ac as r,ad as o,ae as c}from"./chunks/framework.DLZEy9Ii.js";const A=JSON.parse('{"title":"Music Assistant 集成","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"music-assistant.md","filePath":"music-assistant.md"}'),n={name:"music-assistant.md"};function l(d,s,u,h,p,M){return e(),a("div",null,[...s[0]||(s[0]=[i('<h1 id="music-assistant-集成" tabindex="-1">Music Assistant 集成 <a class="header-anchor" href="#music-assistant-集成" aria-label="Permalink to “Music Assistant 集成”">​</a></h1><p>相关文档：<a href="/music-free-site/device.html">设备</a> · <a href="/music-free-site/serve.html">MusicFreeServe 集成</a> · <a href="/music-free-site/user.html">用户</a></p><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><p><a href="https://music-assistant.io/" target="_blank" rel="noreferrer">Music Assistant</a> 是一个开源的本地音乐媒体管理器，像一个音乐界的「万能遥控器」，支持 <strong>AirPlay、Chromecast、DLNA、Snapcast、MQTT</strong> 等多种协议，兼容新老设备。</p><p>MusicFree 原生只支持 <strong>DLNA</strong> 设备；AirPlay、Chromecast 等其他协议因社区第三方库实现差异无法直接集成。接入 Music Assistant 后，即可把 <strong>单曲、专辑、歌单</strong> 播放到 Music Assistant 发现的任意 Player，从而把音乐推送到更多硬件设备。</p><p><img src="'+r+'" alt="Music Assistant"></p><blockquote><p>设备侧的完整说明见 <a href="/music-free-site/device.html">设备模块</a>；该能力自 <strong>V1.2.3</strong> 起提供。</p></blockquote><h2 id="_2-前置条件" tabindex="-1">2. 前置条件 <a class="header-anchor" href="#_2-前置条件" aria-label="Permalink to “2. 前置条件”">​</a></h2><ol><li>部署 <strong>Music Assistant</strong>（一般以 Docker <code>host</code> 网络模式部署，Web 访问端口为 <code>8095</code>）。</li><li>在 Music Assistant 中获取访问授权 <strong>token</strong>。</li><li>在 Music Assistant 中添加音乐源，选择 <strong>OpenSubsonic Media Server Library</strong> 插件，配置 MusicFree 的地址、用户名与密码，等待同步完成。</li></ol><blockquote><p><strong>重要</strong>：Music Assistant 默认使用<strong>自己的音乐库</strong>播放。因此推送到 Music Assistant 的曲目必须已存在于其库中——请确保上面的 OpenSubsonic 音乐源已同步。MusicFree 支持完整的 OpenSubsonic 协议，可被 Music Assistant 作为媒体库接入。</p></blockquote><h2 id="_3-在-musicfree-中配置-管理员" tabindex="-1">3. 在 MusicFree 中配置（管理员） <a class="header-anchor" href="#_3-在-musicfree-中配置-管理员" aria-label="Permalink to “3. 在 MusicFree 中配置（管理员）”">​</a></h2><p>进入「系统配置」，填写 Music Assistant 的访问地址与 token 并启用：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>是否启用 Music Assistant 集成</td><td><code>false</code></td></tr><tr><td><code>server_url</code></td><td>Music Assistant 服务地址，如 <code>http://host:8095</code></td><td></td></tr><tr><td><code>token</code></td><td>Music Assistant 访问授权 token</td><td></td></tr><tr><td><code>refresh_interval</code></td><td>设备刷新间隔（Go duration，如 <code>30s</code>）</td><td><code>30s</code></td></tr></tbody></table><ul><li>保存后会<strong>热更新</strong>：立即重启 Music Assistant 客户端，无需重启 MusicFree 服务。</li><li>配置持久化到数据库（数据库优先，<code>config.yaml</code> 兜底）。</li></ul><p><img src="'+o+'" alt="Music Assistant 配置"></p><blockquote><p>也可直接通过管理接口读写配置：<code>GET</code> / <code>PUT /rest/api/v1/music-assistant/config</code>（需管理员认证）。</p></blockquote><h2 id="_4-添加与使用-player" tabindex="-1">4. 添加与使用 Player <a class="header-anchor" href="#_4-添加与使用-player" aria-label="Permalink to “4. 添加与使用 Player”">​</a></h2><ol><li>启用后，进入「设备发现」页即可看到 Music Assistant 发现的局域网 Player；</li><li>在设备管理页将其 <strong>加入设备列表</strong>；</li><li>管理员可将设备 <strong>授权</strong> 给某个普通用户，授权后该用户即可用此设备播放。</li></ol><p><img src="'+c+'" alt="Music Assistant Player"></p><p>普通用户在音乐、专辑、歌单等页面点击播放到设备时，即可选择 Music Assistant 的 Player。</p><h2 id="_5-播放原理" tabindex="-1">5. 播放原理 <a class="header-anchor" href="#_5-播放原理" aria-label="Permalink to “5. 播放原理”">​</a></h2><p>播放时，MusicFree 会：</p><ol><li>按曲目的 <strong>标题 + 艺术家</strong> 在 Music Assistant 库中查找（<code>library_only</code>，仅库内匹配）；</li><li>解析出对应的 <code>library://</code> URI；</li><li>通过 <code>player_queues/play_media</code> 将曲目推送到目标 Player。</li></ol><p>因此，<strong>在 Music Assistant 库中不存在的曲目无法播放</strong>，会表现为「曲目不存在」或无声音。请先在 Music Assistant 中完成 MusicFree 音乐源的同步。</p><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to “6. 常见问题”">​</a></h2><p><strong>Q：设备发现页看不到 Music Assistant 的 Player？</strong><br> A：请确认：已在「系统配置」中填写地址与 token 并<strong>启用</strong>；Music Assistant 已正常部署且与 MusicFree 处于同一局域网；Music Assistant 中已配置音乐源并同步完成。可稍等片刻后重新进入发现页或刷新。</p><p><strong>Q：推送到 Music Assistant 后没有声音或提示「曲目不存在」？</strong><br> A：Music Assistant 默认使用自己的音乐库播放，只有其库中存在的曲目才能播放。请在 Music Assistant 中通过 <code>OpenSubsonic Media Server Library</code> 插件配置 MusicFree 并等待同步完成。</p><p><strong>Q：修改配置需要重启服务吗？</strong><br> A：不需要。保存配置后 Music Assistant 客户端会热更新重启，新的设备发现使用最新配置。</p><p><strong>Q：普通用户能自己配置 Music Assistant 吗？</strong><br> A：不能。配置为管理员能力；普通用户只能使用管理员已添加并授权给他们的 Player。</p>',29)])])}const _=t(n,[["render",l]]);export{A as __pageData,_ as default};
